bool Sexy::Extract2DOnlyResources(PrimeResourceManager* theManager)  // 0x704c10 (bejeweled3)
{
	RegisterResourceGlobals(theManager);
	try {
		IMAGE_2DONLY_MAINMENU_BACKGROUND = GetImageThrow(theManager, IMAGE_2DONLY_MAINMENU_BACKGROUND_ID, 0);
		IMAGE_2DONLY_MAINMENU_FOREGROUND = GetImageThrow(theManager, IMAGE_2DONLY_MAINMENU_FOREGROUND_ID, 0);
		IMAGE_2DONLY_QUESTMENU_BACKGROUND = GetImageThrow(theManager, IMAGE_2DONLY_QUESTMENU_BACKGROUND_ID, 0);
		IMAGE_2DONLY_QUESTMENU_BACKPILLARS = GetImageThrow(theManager, IMAGE_2DONLY_QUESTMENU_BACKPILLARS_ID, 0);
		IMAGE_2DONLY_QUESTMENU_FLOOR = GetImageThrow(theManager, IMAGE_2DONLY_QUESTMENU_FLOOR_ID, 0);
		IMAGE_2DONLY_QUESTMENU_FRONTPILLARS = GetImageThrow(theManager, IMAGE_2DONLY_QUESTMENU_FRONTPILLARS_ID, 0);
	} catch (ResourceManagerException&) {
		return false;
	}
	return true;
}

void Sexy::RegisterResourceGlobals(PrimeResourceManager* theManager)
{
	for (int anId = 0; anId < RESOURCE_ID_MAX; anId++) {
		theManager->RegisterGlobalPtr(gResourceNames[anId], (void**)gResources[anId]);
		gImageOffsets[anId] = theManager->GetImageOffset(gResourceNames[anId]);
	}
}

void* Sexy::GetResourceById(int theId) { return theId == -1 ? nullptr : *(void**)gResources[theId]; }
int Sexy::GetImageOffsetX(int theId) { return gImageOffsets[theId].mX; }
int Sexy::GetImageOffsetY(int theId) { return gImageOffsets[theId].mY; }
const char* Sexy::GetStringIdById(int theId) { return (unsigned)theId < RESOURCE_ID_MAX ? gResourceNames[theId] : ""; }

// The original fills a map from the names once (the later of two equal names wins) and looks the name up in it
int Sexy::GetIdByStringId(const char* theName)
{
	static std::map<std::string, int> aMap;
	if (aMap.empty()) {
		for (int anId = 0; anId < RESOURCE_ID_MAX; anId++)
			aMap[gResourceNames[anId]] = anId;
	}
	std::map<std::string, int>::iterator anItr = aMap.find(theName);
	return anItr == aMap.end() ? -1 : anItr->second;
}

bool Sexy::ExtractInitResources(PrimeResourceManager* theManager)  // 0x70e260 (bejeweled3)
{
	RegisterResourceGlobals(theManager);
	if (theManager->mCurArtRes == 600 && !ExtractInit600Resources(theManager))
		return false;
	if (theManager->mCurArtRes == 768 && !ExtractInit768Resources(theManager))
		return false;
	if (theManager->mCurArtRes == 1200 && !ExtractInit1200Resources(theManager))
		return false;
	if (!ExtractInitCommonResources(theManager))
		return false;
	return true;
}

